<script setup>
import Icon from './Icon.vue'
import {formatPrice,thumbUrl} from '../lib/domain'
import placeholder from '../assets/placeholder-property.svg'
defineProps({property:Object,favorite:Boolean,manage:Boolean,brand:Object})
defineEmits(['open','favorite','edit'])
</script>
<template><article class="property-card"><div class="property-photo"><img v-if="property.image" :src="thumbUrl(property.image)" :alt="property.type + ' en ' + property.commune" loading="lazy" decoding="async" @error="$event.target.style.display='none'"><img v-else :src="placeholder" alt="" class="photo-placeholder"><span class="photo-label">{{property.operation}}</span><button v-if="!manage" class="favorite" :class="{selected:favorite}" :aria-label="favorite ? 'Quitar de favoritos' : 'Guardar en favoritos'" :aria-pressed="favorite" @click="$emit('favorite',property.id)"><Icon name="heart"/></button><span v-else class="photo-status">{{property.status}}</span></div><div class="property-body"><div v-if="brand?.name" class="publication-brand"><img v-if="brand.logo" :src="brand.logo" alt="" @error="$event.target.style.display='none'"><span>{{brand.name}}</span></div><div class="property-location"><Icon name="pin"/>{{property.commune}} · {{property.sector || property.type}}</div><button class="card-title" @click="$emit('open',property)">{{property.title}}</button><div class="property-specs"><span><Icon name="bed"/>{{property.beds}} dorm.</span><span><Icon name="bath"/>{{property.baths}} baños</span><span><Icon name="area"/>{{property.area}} m²</span></div><div class="property-bottom"><strong>{{formatPrice(property)}}</strong><button class="text-button" @click="manage ? $emit('edit',property) : $emit('open',property)">{{manage ? 'Administrar' : 'Ver propiedad'}}<Icon name="arrow"/></button></div></div></article></template>
